import math
from numbers import Real


def _validate_stop(stop):
    if not isinstance(stop, tuple) or len(stop) != 2:
        raise TypeError("a stop must be a coordinate tuple")
    for coordinate in stop:
        if isinstance(coordinate, bool) or not isinstance(coordinate, Real):
            raise TypeError("coordinates must be real numbers")
        if not math.isfinite(coordinate):
            raise ValueError("coordinates must be finite")


class RoutePlan:
    def __init__(self, stops):
        if not isinstance(stops, list):
            raise TypeError("stops must be a list")
        for stop in stops:
            _validate_stop(stop)
        self._stops = stops

    def add_stop(self, stop):
        _validate_stop(stop)
        self._stops.append(stop)

    def total_manhattan_distance(self):
        total = 0.0
        for first, second in zip(self._stops, self._stops[1:]):
            total += abs(second[0] - first[0]) + abs(second[1] - first[1])
        return float(total)

    def snapshot(self):
        return tuple(self._stops)

